class BasketCampaign(Campaign):
    coupon = models.OneToOneField(
        "Coupon", null=True, blank=True, related_name="campaign", verbose_name=_("coupon"), on_delete=models.CASCADE
    )
    @classmethod
    def get_matching(cls, basket, lines):
        matching = []
        exclude_condition_ids = set()
        product_id_to_qty = get_product_ids_and_quantities(basket)
        lines_suppliers = get_lines_suppliers(basket)
        products_in_basket_conditions_to_check = set(
            ProductsInBasketCondition.objects.filter(products__id__in=product_id_to_qty.keys()).values_list(
                "id", flat=True
            )
        )
        exclude_condition_ids |= set(
            ProductsInBasketCondition.objects.exclude(id__in=products_in_basket_conditions_to_check).values_list(
                "id", flat=True
            )
        )
        categories = set(
            Category.objects.filter(shop_products__product_id__in=product_id_to_qty.keys()).values_list("id", flat=True)
        )
        category_products_in_basket_to_check = set(
            CategoryProductsBasketCondition.objects.filter(categories__in=categories).values_list("id", flat=True)
        )
        exclude_condition_ids |= set(
            CategoryProductsBasketCondition.objects.exclude(id__in=category_products_in_basket_to_check).values_list(
                "id", flat=True
            )
        )
        queryset = cls.objects.filter(active=True, shop=basket.shop)
        if exclude_condition_ids:
            queryset = queryset.exclude(conditions__id__in=exclude_condition_ids)
        if lines_suppliers:
            queryset = queryset.filter(Q(supplier__isnull=True) | Q(supplier__in=lines_suppliers))
        for campaign in queryset.prefetch_related("conditions").distinct():
            if campaign.rules_match(basket, lines):
                matching.append(campaign)
        return matching
class AttributableMixin(object):
    @classmethod
    def cache_attributes_for_targets(cls, applied_attr_cls, targets, attribute_identifiers, language):
        if not settings.SHUUP_ENABLE_ATTRIBUTES:
            return targets
        applied_attrs_by_target_id = defaultdict(list)
        attr_ids = set()
        filter_kwargs = {
            "%s_id__in" % (applied_attr_cls._applied_fk_field): (t.pk for t in targets),
            "attribute__identifier__in": attribute_identifiers,
        }
        for applied_attr in applied_attr_cls.objects.language(language).filter(**filter_kwargs):
            attr_ids.add(applied_attr.attribute_id)
            applied_attrs_by_target_id[applied_attr.product_id].append(applied_attr)
        attr_map = dict((attr.id, attr) for attr in Attribute.objects.language(language).filter(id__in=attr_ids))
        for target in targets:
            for identifier in attribute_identifiers:
                target._set_cached_attribute(language, identifier, NoSuchAttributeHere)
            for applied_attr in applied_attrs_by_target_id.get(target.id, ()):
                setattr(
                    applied_attr, applied_attr.__class__.attribute.field.name, attr_map.get(applied_attr.attribute_id)
                )
                target._set_cached_attribute(language, applied_attr.attribute.identifier, applied_attr)
        return targets
