class AccessChecker(object):
    def find_access_rule(self, url, ts=None, urlkey=None, collection=None, acl_user=None):
        """Attempts to find the access control rule for the
        supplied URL otherwise returns the default rule
        :param str url: The URL for the rule to be found
        :param str|None ts: A timestamp (not used)
        :param str|None urlkey: The access control url key
        :param str|None collection: The collection, if any
        :param str|None acl_user: The access control user, if any
        :return: The access control rule for the supplied URL
        if one exists otherwise the default rule
        :rtype: CDXObject
        """
        params = {'url': url,
                  'urlkey': urlkey,
                  'nosource': 'true',
                  'exact_match_suffix': self.EXACT_SUFFIX_SEARCH_B
                 }
        if collection:
            params['param.coll'] = collection
        acl_iter, errs = self.aggregator(params)
        if errs:
            print(errs)
        key = params['key']
        key_exact = key + self.EXACT_SUFFIX_B
        tld = key.split(b',')[0]
        last_obj = None
        last_key = None
        for acl in acl_iter:
            if not acl:
                continue
            acl_key = acl.split(b' ')[0]
            acl_obj = None
            if acl_key != last_key and last_obj:
                return last_obj
            if key_exact == acl_key:
                acl_obj = CDXObject(acl)
            if key.startswith(acl_key):
                acl_obj = CDXObject(acl)
            if acl_obj:
                user = acl_obj.get('user')
                if user == acl_user:
                    return acl_obj
                elif not user:
                    last_key = acl_key
                    last_obj = acl_obj
            if acl_key < tld:
                break
        return last_obj if last_obj else self.default_rule
def no_except_close(closable):
    """Attempts to call the close method of the
    supplied object catching all exceptions.
    Also tries to call release_conn() in case a requests raw stream
    :param closable: The object to be closed
    :rtype: None
    """
    try:
        closable.close()
    except Exception:
        pass
    try:
        closable.release_conn()
    except Exception:
        pass
def StreamIter(stream, header1=None, header2=None, size=BUFF_SIZE, closer=closing):
    with closer(stream):
        if header1:
            yield header1
        if header2:
            yield header2
        while True:
            buff = stream.read(size)
            if not buff:
                break
            yield buff
class ResolvingLoader(object):
    def __call__(self, cdx, failed_files, cdx_loader, *args, **kwargs):
        headers_record, payload_record = self.load_headers_and_payload(cdx, failed_files, cdx_loader)
        if not headers_record:
            headers_record = payload_record
        elif headers_record != payload_record:
            no_except_close(headers_record.raw_stream)
            if not headers_record.http_headers.headers:
                headers_record = payload_record
        if not headers_record or not payload_record:
            if headers_record:
                no_except_close(headers_record.raw_stream)
            if payload_record:
                no_except_close(payload_record.raw_stream)
            raise ArchiveLoadFailed('Could not load ' + str(cdx))
        headers_record.http_headers.validate_statusline('204 No Content')
        return (headers_record.http_headers, payload_record.raw_stream)
