        url = res_template(self.timemap_url, params)
        headers = self._get_headers(params)
        res = None
        try:
            res = self.sesh.get(url,
                                headers=headers,
                                timeout=params.get('_timeout'))
            res.raise_for_status()
            assert(res.text)
        except Exception as e:
            no_except_close(res)
