class AdbClient(Logger):
    def transport(self, serial=None, try_again=True):
        """Sets the Transport on the remote device.
        Examples:
            >>> pwnlib.protocols.adb.AdbClient().transport()
        """
        if not serial and context.device:
            serial = context.device
        if serial:
            serial = str(serial)
            msg = 'host:transport:%s' % serial
        else:
            msg = 'host:transport-any'
        if self.send(msg) == FAIL:
            err = self.recvl().decode('utf-8')
            if err == 'device offline' and try_again:
                self.wait_for_device(serial)
                return self.transport(serial, try_again=False)
            if serial:
                self.error("Could not set transport to %r (%s)" % (serial, err))
            else:
                self.error("Could not set transport 'any' (%s)" % err)
    @_with_transport
    @_sync
    def _write(self, path, data, mode=0o755, timestamp=None, callback=None):
        path += ',' + str(mode)
        self.c.flat32('SEND', len(path), path)
        sent = 0
        for chunk in group(0x10000, data):
            self.c.flat32('DATA', len(chunk), chunk)
            if callback:
                callback(path, data[:sent], len(data), chunk, len(chunk))
            sent += len(chunk)
        if timestamp is None:
            timestamp = int(time.time())
        self.c.flat32('DONE', timestamp)
        result = self.c.recvn(4)
        if result != OKAY:
            log.error("Sync write failed: %r (expected OKAY)" % result)
        return
@python_2_bytes_compatible
class FileStructure(object):
    def __getattr__(self,item):
        if item in FileStructure.__dict__ or item in self.vars_:
            return object.__getattribute__(self,item)
        log.error("Unknown variable %r" % item)
    def struntil(self,v):
        r"""
        Payload for stuff till 'v' where 'v' is a structure member. This payload includes 'v' as well.
        Arguments:
            v(string)
                The name of the field uptil which the payload should be created.
        Example:
            Payload for data uptil _IO_buf_end
            >>> context.clear(arch='amd64')
            >>> fileStr = FileStructure(0xdeadbeef)
            >>> payload = fileStr.struntil("_IO_buf_end")
            >>> payload
            b'\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00'
        """
        if v not in self.vars_:
            return b''
        structure = b''
        for val in self.vars_:
            if isinstance(self.__getattr__(val), bytes):
                structure += self.__getattr__(val).ljust(context.bytes, b'\x00')
            else:
                structure += pack(self.__getattr__(val), self.length[val]*8)
            if val == v:
                break
        return structure[:-1]
