        if isinstance(k, six.integer_types):
            if k >= large_key:
                k = fill(pack(k))
        elif isinstance(k, six.text_type):
            k = fill(k.encode('utf8'))
        elif isinstance(k, (bytearray, bytes)):
            k = fill(k)
