class PurgeHistoryRestServlet(ClientV1RestServlet):
    @defer.inlineCallbacks
    def on_POST(self, request, room_id, event_id):
        requester = yield self.auth.get_user_by_req(request)
        is_admin = yield self.auth.is_server_admin(requester.user)
        if not is_admin:
            raise AuthError(403, "You are not a server admin")
        body = parse_json_object_from_request(request, allow_empty_body=True)
        delete_local_events = bool(body.get("delete_local_events", False))
        if event_id is None:
            event_id = body.get('purge_up_to_event_id')
        if event_id is not None:
            event = yield self.store.get_event(event_id)
            if event.room_id != room_id:
                raise SynapseError(400, "Event is for wrong room.")
            token = yield self.store.get_topological_token_for_event(event_id)
            logger.info(
                "[purge] purging up to token %s (event_id %s)",
                token, event_id,
            )
        elif 'purge_up_to_ts' in body:
            ts = body['purge_up_to_ts']
            if not isinstance(ts, int):
                raise SynapseError(
                    400, "purge_up_to_ts must be an int",
                    errcode=Codes.BAD_JSON,
                )
            stream_ordering = (
                yield self.store.find_first_stream_ordering_after_ts(ts)
            )
            r = (
                yield self.store.get_room_event_after_stream_ordering(
                    room_id, stream_ordering,
                )
            )
            if not r:
                logger.warn(
                    "[purge] purging events not possible: No event found "
                    "(received_ts %i => stream_ordering %i)",
                    ts, stream_ordering,
                )
                raise SynapseError(
                    404,
                    "there is no event to be purged",
                    errcode=Codes.NOT_FOUND,
                )
            (stream, topo, _event_id) = r
            token = "t%d-%d" % (topo, stream)
            logger.info(
                "[purge] purging up to token %s (received_ts %i => "
                "stream_ordering %i)",
                token, ts, stream_ordering,
            )
        else:
            raise SynapseError(
                400,
                "must specify purge_up_to_event_id or purge_up_to_ts",
                errcode=Codes.BAD_JSON,
            )
        purge_id = yield self.pagination_handler.start_purge_history(
            room_id, token,
            delete_local_events=delete_local_events,
        )
        defer.returnValue((200, {
            "purge_id": purge_id,
        }))
def create_resource_tree(desired_tree, root_resource):
    """Create the resource tree for this Home Server.
    This in unduly complicated because Twisted does not support putting
    child resources more than 1 level deep at a time.
    Args:
        web_client (bool): True to enable the web client.
        root_resource (twisted.web.resource.Resource): The root
            resource to add the tree to.
    Returns:
        twisted.web.resource.Resource: the ``root_resource`` with a tree of
        child resources added to it.
    """
    resource_mappings = {}
    for full_path, res in desired_tree.items():
        full_path = full_path.encode("utf-8")
        logger.info("Attaching %s to path %s", res, full_path)
        last_resource = root_resource
        for path_seg in full_path.split(b'/')[1:-1]:
            if path_seg not in last_resource.listNames():
                child_resource = NoResource()
                last_resource.putChild(path_seg, child_resource)
                res_id = _resource_id(last_resource, path_seg)
                resource_mappings[res_id] = child_resource
                last_resource = child_resource
            else:
                res_id = _resource_id(last_resource, path_seg)
                last_resource = resource_mappings[res_id]
        last_path_seg = full_path.split(b'/')[-1]
        res_id = _resource_id(last_resource, last_path_seg)
        if res_id in resource_mappings:
            existing_dummy_resource = resource_mappings[res_id]
            for child_name in existing_dummy_resource.listNames():
                child_res_id = _resource_id(
                    existing_dummy_resource, child_name
                )
                child_resource = resource_mappings[child_res_id]
                res.putChild(child_name, child_resource)
        last_resource.putChild(last_path_seg, res)
        res_id = _resource_id(last_resource, last_path_seg)
        resource_mappings[res_id] = res
    return root_resource
def serialize_event(e, time_now_ms, as_client_event=True,
                    event_format=format_event_for_client_v1,
                    token_id=None, only_event_fields=None, is_invite=False):
    """Serialize event for clients
    Args:
        e (EventBase)
        time_now_ms (int)
        as_client_event (bool)
        event_format
        token_id
        only_event_fields
        is_invite (bool): Whether this is an invite that is being sent to the
            invitee
    Returns:
        dict
    """
    if not isinstance(e, EventBase):
        return e
    time_now_ms = int(time_now_ms)
    d = {k: v for k, v in e.get_dict().items()}
    if "age_ts" in d["unsigned"]:
        d["unsigned"]["age"] = time_now_ms - d["unsigned"]["age_ts"]
        del d["unsigned"]["age_ts"]
    if "redacted_because" in e.unsigned:
        d["unsigned"]["redacted_because"] = serialize_event(
            e.unsigned["redacted_because"], time_now_ms,
            event_format=event_format
        )
    if token_id is not None:
        if token_id == getattr(e.internal_metadata, "token_id", None):
            txn_id = getattr(e.internal_metadata, "txn_id", None)
            if txn_id is not None:
                d["unsigned"]["transaction_id"] = txn_id
    if not is_invite:
        d["unsigned"].pop("invite_room_state", None)
    if as_client_event:
        d = event_format(d)
    if only_event_fields:
        if (not isinstance(only_event_fields, list) or
                not all(isinstance(f, string_types) for f in only_event_fields)):
            raise TypeError("only_event_fields must be a list of strings")
        d = only_fields(d, only_event_fields)
    return d
class PaginationHandler(object):
    @defer.inlineCallbacks
    def get_messages(self, requester, room_id=None, pagin_config=None,
                     as_client_event=True, event_filter=None):
        """Get messages in a room.
        Args:
            requester (Requester): The user requesting messages.
            room_id (str): The room they want messages from.
            pagin_config (synapse.api.streams.PaginationConfig): The pagination
                config rules to apply, if any.
            as_client_event (bool): True to get events in client-server format.
            event_filter (Filter): Filter to apply to results or None
        Returns:
            dict: Pagination API results
        """
        user_id = requester.user.to_string()
        if pagin_config.from_token:
            room_token = pagin_config.from_token.room_key
        else:
            pagin_config.from_token = (
                yield self.hs.get_event_sources().get_current_token_for_room(
                    room_id=room_id
                )
            )
            room_token = pagin_config.from_token.room_key
        room_token = RoomStreamToken.parse(room_token)
        pagin_config.from_token = pagin_config.from_token.copy_and_replace(
            "room_key", str(room_token)
        )
        source_config = pagin_config.get_source_config("room")
        with (yield self.pagination_lock.read(room_id)):
            membership, member_event_id = yield self.auth.check_in_room_or_world_readable(
                room_id, user_id
            )
            if source_config.direction == 'b':
                if room_token.topological:
                    max_topo = room_token.topological
                else:
                    max_topo = yield self.store.get_max_topological_token(
                        room_id, room_token.stream
                    )
                if membership == Membership.LEAVE:
                    leave_token = yield self.store.get_topological_token_for_event(
                        member_event_id
                    )
                    leave_token = RoomStreamToken.parse(leave_token)
                    if leave_token.topological < max_topo:
                        source_config.from_key = str(leave_token)
                yield self.hs.get_handlers().federation_handler.maybe_backfill(
                    room_id, max_topo
                )
            events, next_key = yield self.store.paginate_room_events(
                room_id=room_id,
                from_key=source_config.from_key,
                to_key=source_config.to_key,
                direction=source_config.direction,
                limit=source_config.limit,
                event_filter=event_filter,
            )
            next_token = pagin_config.from_token.copy_and_replace(
                "room_key", next_key
            )
        if not events:
            defer.returnValue({
                "chunk": [],
                "start": pagin_config.from_token.to_string(),
                "end": next_token.to_string(),
            })
        if event_filter:
            events = event_filter.filter(events)
        events = yield filter_events_for_client(
            self.store,
            user_id,
            events,
            is_peeking=(member_event_id is None),
        )
        state = None
        if event_filter and event_filter.lazy_load_members():
            types = [
                (EventTypes.Member, state_key)
                for state_key in set(
                    event.sender
                    for event in events
                )
            ]
            state_ids = yield self.store.get_state_ids_for_event(
                events[0].event_id, types=types,
            )
            if state_ids:
                state = yield self.store.get_events(list(state_ids.values()))
            if state:
                state = yield filter_events_for_client(
                    self.store,
                    user_id,
                    state.values(),
                    is_peeking=(member_event_id is None),
                )
        time_now = self.clock.time_msec()
        chunk = {
            "chunk": [
                serialize_event(e, time_now, as_client_event)
                for e in events
            ],
            "start": pagin_config.from_token.to_string(),
            "end": next_token.to_string(),
        }
        if state:
            chunk["state"] = [
                serialize_event(e, time_now, as_client_event)
                for e in state
            ]
        defer.returnValue(chunk)
