def unfreeze(o):
    t = type(o)
    if t is dict or t is frozendict:
        return dict({k: unfreeze(v) for k, v in o.items()})
    if t is str or t is unicode:
        return o
    try:
        return [unfreeze(i) for i in o]
    except TypeError:
        pass
    return o
