    @defer.inlineCallbacks
    def send_join(self, destinations, pdu):
        """Sends a join event to one of a list of homeservers.
        Doing so will cause the remote server to add the event to the graph,
        and send the event out to the rest of the federation.
        Args:
            destinations (str): Candidate homeservers which are probably
                participating in the room.
            pdu (BaseEvent): event to be sent
        Return:
            Deferred: resolves to a dict with members ``origin`` (a string
            giving the serer the event was sent to, ``state`` (?) and
            ``auth_chain``.
            Fails with a ``CodeMessageException`` if the chosen remote server
            returns a 300/400 code.
            Fails with a ``RuntimeError`` if no servers were reachable.
        """
        for destination in destinations:
            if destination == self.server_name:
                continue
            try:
                time_now = self._clock.time_msec()
                _, content = yield self.transport_layer.send_join(
                    destination=destination,
                    room_id=pdu.room_id,
                    event_id=pdu.event_id,
                    content=pdu.get_pdu_json(time_now),
                )
                logger.debug("Got content: %s", content)
                state = [
                    event_from_pdu_json(p, outlier=True)
                    for p in content.get("state", [])
                ]
                auth_chain = [
                    event_from_pdu_json(p, outlier=True)
                    for p in content.get("auth_chain", [])
                ]
                pdus = {
                    p.event_id: p
                    for p in itertools.chain(state, auth_chain)
                }
                valid_pdus = yield self._check_sigs_and_hash_and_fetch(
                    destination, pdus.values(),
                    outlier=True,
                )
                valid_pdus_map = {
                    p.event_id: p
                    for p in valid_pdus
                }
                signed_state = [
                    copy.copy(valid_pdus_map[p.event_id])
                    for p in state
                    if p.event_id in valid_pdus_map
                ]
                signed_auth = [
                    valid_pdus_map[p.event_id]
                    for p in auth_chain
                    if p.event_id in valid_pdus_map
                ]
                for s in signed_state:
                    s.internal_metadata = copy.deepcopy(s.internal_metadata)
                auth_chain.sort(key=lambda e: e.depth)
                defer.returnValue({
                    "state": signed_state,
                    "auth_chain": signed_auth,
                    "origin": destination,
                })
            except CodeMessageException as e:
                if not 500 <= e.code < 600:
                    raise
                else:
                    logger.exception(
                        "Failed to send_join via %s: %s",
                        destination, e.message
                    )
            except Exception as e:
                logger.exception(
                    "Failed to send_join via %s: %s",
                    destination, e.message
                )
        raise RuntimeError("Failed to send to any server.")
    @defer.inlineCallbacks
    def send_invite(self, destination, room_id, event_id, pdu):
        time_now = self._clock.time_msec()
        code, content = yield self.transport_layer.send_invite(
            destination=destination,
            room_id=room_id,
            event_id=event_id,
            content=pdu.get_pdu_json(time_now),
        )
        pdu_dict = content["event"]
        logger.debug("Got response to send_invite: %s", pdu_dict)
        pdu = event_from_pdu_json(pdu_dict)
        pdu = yield self._check_sigs_and_hash(pdu)
        defer.returnValue(pdu)
    @defer.inlineCallbacks
    def query_auth(self, destination, room_id, event_id, local_auth):
        """
        Params:
            destination (str)
            event_it (str)
            local_auth (list)
        """
        time_now = self._clock.time_msec()
        send_content = {
            "auth_chain": [e.get_pdu_json(time_now) for e in local_auth],
        }
        code, content = yield self.transport_layer.send_query_auth(
            destination=destination,
            room_id=room_id,
            event_id=event_id,
            content=send_content,
        )
        auth_chain = [
            event_from_pdu_json(e)
            for e in content["auth_chain"]
        ]
        signed_auth = yield self._check_sigs_and_hash_and_fetch(
            destination, auth_chain, outlier=True
        )
        signed_auth.sort(key=lambda e: e.depth)
        ret = {
            "auth_chain": signed_auth,
            "rejects": content.get("rejects", []),
            "missing": content.get("missing", []),
        }
        defer.returnValue(ret)
    @defer.inlineCallbacks
    def get_missing_events(self, destination, room_id, earliest_events_ids,
                           latest_events, limit, min_depth, timeout):
        """Tries to fetch events we are missing. This is called when we receive
        an event without having received all of its ancestors.
        Args:
            destination (str)
            room_id (str)
            earliest_events_ids (list): List of event ids. Effectively the
                events we expected to receive, but haven't. `get_missing_events`
                should only return events that didn't happen before these.
            latest_events (list): List of events we have received that we don't
                have all previous events for.
            limit (int): Maximum number of events to return.
            min_depth (int): Minimum depth of events tor return.
            timeout (int): Max time to wait in ms
        """
        try:
            content = yield self.transport_layer.get_missing_events(
                destination=destination,
                room_id=room_id,
                earliest_events=earliest_events_ids,
                latest_events=[e.event_id for e in latest_events],
                limit=limit,
                min_depth=min_depth,
                timeout=timeout,
            )
            events = [
                event_from_pdu_json(e)
                for e in content.get("events", [])
            ]
            signed_events = yield self._check_sigs_and_hash_and_fetch(
                destination, events, outlier=False
            )
        except HttpResponseException as e:
            if not e.code == 400:
                raise
            signed_events = []
        defer.returnValue(signed_events)
