        self.config.meta_set('catchall', 'validate', bool)
        self.config['catchall'] = catchall
        self.config['autojson'] = autojson
        self.resources = ResourceManager()
        self.routes = []
        self.router = Router()
        self.error_handler = {}
        self.plugins = []
        if self.config['autojson']:
            self.install(JSONPlugin())
