def calculate_largest_base(b: int, num_bits: int, is_signed: bool) -> Tuple[int, int]:
    """
    For a given power `b`, compute the maximum base `a` that will not produce an
    overflow in the equation `a ** b`
    Arguments
    ---------
    b : int
        Power value for the equation `a ** b`
    num_bits : int
        The maximum number of bits that the resulting value must fit in
    is_signed : bool
        Is the operation being performed on signed integers?
    Returns
    -------
    Tuple[int, int]
        Smallest and largest possible values for `a` where the result
        does not overflow `num_bits`.
        Note that the lower and upper bounds are not always negatives of
        each other, due to lower/upper bounds for int_<value_bits> being
        slightly asymmetric.
    """
    if num_bits % 8:
        raise CompilerPanic("Type is not a modulo of 8")
    if b in (0, 1):
        raise CompilerPanic("Exponential operation is useless!")
    if b < 0:
        raise TypeCheckFailure("Cannot calculate negative exponents")
    value_bits = num_bits - (1 if is_signed else 0)
    if b > value_bits:
        raise TypeCheckFailure("Value is too large and will always throw")
    a = math.ceil(2 ** (decimal.Decimal(value_bits) / decimal.Decimal(b)))
    num_iterations = 0
    while (a + 1) ** b < 2**value_bits:
        a += 1
        num_iterations += 1
        assert num_iterations < 10000
    while a**b >= 2**value_bits:
        a -= 1
        num_iterations += 1
        assert num_iterations < 10000
    if not is_signed:
        return 0, a
    if (a + 1) ** b == (2**value_bits):
        return -(a + 1), a
    else:
        return -a, a
def get_node(
    ast_struct: Union[dict, python_ast.AST], parent: Optional["VyperNode"] = None
) -> "VyperNode":
    """
    Convert an AST structure to a vyper AST node.
    This is a recursive call, all child nodes of the input value are also
    converted to Vyper nodes.
    Parameters
    ----------
    ast_struct: dict | AST
        Annotated python AST node or vyper AST dict to generate the node from.
    parent: VyperNode, optional
        Parent node of the node being created.
    Returns
    -------
    VyperNode
        The generated AST object.
    """
    if not isinstance(ast_struct, dict):
        ast_struct = ast_struct.__dict__
        if "parent" in ast_struct:
            ast_struct = copy.copy(ast_struct)
            del ast_struct["parent"]
    if ast_struct["ast_type"] == "AnnAssign" and isinstance(parent, Module):
        if getattr(ast_struct["target"], "id", None) == "implements":
            if ast_struct["value"] is not None:
                _raise_syntax_exc("`implements` cannot have a value assigned", ast_struct)
            ast_struct["ast_type"] = "ImplementsDecl"
        else:
            ast_struct["ast_type"] = "VariableDecl"
    vy_class = getattr(sys.modules[__name__], ast_struct["ast_type"], None)
    if not vy_class:
        if ast_struct["ast_type"] == "Delete":
            _raise_syntax_exc("Deleting is not supported", ast_struct)
        elif ast_struct["ast_type"] in ("ExtSlice", "Slice"):
            _raise_syntax_exc("Vyper does not support slicing", ast_struct)
        elif ast_struct["ast_type"] == "UAdd":
            _raise_syntax_exc("Vyper does not support + as a unary operator", parent)
        else:
            _raise_syntax_exc(
                f"Invalid syntax (unsupported '{ast_struct['ast_type']}' Python AST node)",
                ast_struct,
            )
    return vy_class(parent=parent, **ast_struct)
class Compare(ExprNode):
    def evaluate(self) -> ExprNode:
        """
        Attempt to evaluate the comparison.
        Returns
        -------
        NameConstant
            Node representing the result of the evaluation.
        """
        left, right = self.left, self.right
        if not isinstance(left, Constant):
            raise UnfoldableNode("Node contains invalid field(s) for evaluation")
        if isinstance(self.op, (In, NotIn)):
            if not isinstance(right, List):
                raise UnfoldableNode("Node contains invalid field(s) for evaluation")
            if next((i for i in right.elements if not isinstance(i, Constant)), None):
                raise UnfoldableNode("Node contains invalid field(s) for evaluation")
            if len(set([type(i) for i in right.elements])) > 1:
                raise UnfoldableNode("List contains multiple literal types")
            value = self.op._op(left.value, [i.value for i in right.elements])
            return NameConstant.from_node(self, value=value)
        if not isinstance(left, type(right)):
            raise UnfoldableNode("Cannot compare different literal types")
        if not isinstance(self.op, (Eq, NotEq)) and not isinstance(left, (Int, Decimal)):
            raise TypeMismatch(f"Invalid literal types for {self.op.description} comparison", self)
        value = self.op._op(left.value, right.value)
        return NameConstant.from_node(self, value=value)
