def set_datasets_permissions(
    permissions_name, resources_names=None, users_usernames=None, groups_names=None, delete_flag=False, verbose=False
):
    from geonode.resource.manager import resource_manager
    resources_as_pk = []
    for el in resources_names or []:
        if isinstance(el, str) and not el.isnumeric():
            res = Dataset.objects.filter(Q(title=el) | Q(name=el))
            if res.exists():
                resources_as_pk.append(res.first().pk)
        else:
            resources_as_pk.append(el)
    not_found = []
    final_perms_payload = {}
    for rpk in resources_as_pk:
        resource = Dataset.objects.filter(pk=rpk)
        if not resource.exists():
            not_found.append(rpk)
            logger.error(f"Resource named: {rpk} not found, skipping....")
            continue
        else:
            resource = resource.first()
            original_perms = PermSpec(resource.get_all_level_info(), resource)
            new_perms_payload = {"organizations": [], "users": [], "groups": []}
            if users_usernames:
                User = get_user_model()
                for _user in users_usernames:
                    try:
                        new_perms_payload["users"].append(
                            {"id": User.objects.get(username=_user).pk, "permissions": permissions_name}
                        )
                    except User.DoesNotExist:
                        logger.warning(f"The user {_user} does not exists. " "It has been skipped.")
            if groups_names:
                for group_name in groups_names:
                    try:
                        new_perms_payload["groups"].append(
                            {"id": Group.objects.get(name=group_name).pk, "permissions": permissions_name}
                        )
                    except Group.DoesNotExist:
                        logger.warning(f"The group {group_name} does not exists. " "It has been skipped.")
            new_compact_perms = PermSpecCompact(new_perms_payload, resource)
            copy_compact_perms = copy.deepcopy(new_compact_perms)
            perms_spec_compact_resource = PermSpecCompact(original_perms.compact, resource)
            perms_spec_compact_resource.merge(new_compact_perms)
            final_perms_payload = perms_spec_compact_resource.extended
            if delete_flag:
                final_perms_payload["users"] = {
                    _user: _perms
                    for _user, _perms in perms_spec_compact_resource.extended["users"].items()
                    if _user not in copy_compact_perms.extended["users"]
                }
                final_perms_payload["groups"] = {
                    _group: _perms
                    for _group, _perms in perms_spec_compact_resource.extended["groups"].items()
                    if _group not in copy_compact_perms.extended["groups"]
                }
                if final_perms_payload["users"].get("AnonymousUser") is None and final_perms_payload["groups"].get(
                    "anonymous"
                ):
                    final_perms_payload["groups"].pop("anonymous")
            resource_manager.set_permissions(resource.uuid, instance=resource, permissions=final_perms_payload)
@requires_csrf_token
def proxy(
    request,
    url=None,
    response_callback=None,
    sec_chk_hosts=True,
    sec_chk_rules=True,
    timeout=None,
    allowed_hosts=[],
    headers=None,
    access_token=None,
    **kwargs,
):
    from geonode.geoserver.helpers import ogc_server_settings
    if not timeout:
        timeout = getattr(ogc_server_settings, "TIMEOUT", TIMEOUT)
    PROXY_ALLOWED_HOSTS = getattr(settings, "PROXY_ALLOWED_HOSTS", ())
    if "url" not in request.GET and not url:
        return HttpResponse(
            "The proxy service requires a URL-encoded URL as a parameter.", status=400, content_type="text/plain"
        )
    raw_url = url or request.GET["url"]
    raw_url = urljoin(settings.SITEURL, raw_url) if raw_url.startswith("/") else raw_url
    url = urlsplit(raw_url)
    scheme = str(url.scheme)
    locator = str(url.path)
    if url.query != "":
        locator += f"?{url.query}"
    if url.fragment != "":
        locator += f"
    site_url = urlsplit(settings.SITEURL)
    if sec_chk_hosts and not settings.DEBUG:
        if site_url.hostname not in PROXY_ALLOWED_HOSTS:
            PROXY_ALLOWED_HOSTS += (site_url.hostname,)
        hostname = (ogc_server_settings.hostname,) if ogc_server_settings else ()
        if hostname not in PROXY_ALLOWED_HOSTS:
            PROXY_ALLOWED_HOSTS += hostname
        if url.query and ows_regexp.match(url.query):
            ows_tokens = ows_regexp.match(url.query).groups()
            if (
                len(ows_tokens) == 4
                and "version" == ows_tokens[0]
                and StrictVersion(ows_tokens[1]) >= StrictVersion("1.0.0")
                and StrictVersion(ows_tokens[1]) <= StrictVersion("3.0.0")
                and ows_tokens[2].lower() in ("getcapabilities")
                and ows_tokens[3].upper() in ("OWS", "WCS", "WFS", "WMS", "WPS", "CSW")
            ):
                if url.hostname not in PROXY_ALLOWED_HOSTS:
                    PROXY_ALLOWED_HOSTS += (url.hostname,)
        from geonode.services.models import Service
        for _s in Service.objects.all():
            _remote_host = urlsplit(_s.base_url).hostname
            PROXY_ALLOWED_HOSTS += (_remote_host,)
        if not validate_host(extract_ip_or_domain(raw_url), PROXY_ALLOWED_HOSTS):
            return HttpResponse(
                "DEBUG is set to False but the host of the path provided to the proxy service"
                " is not in the PROXY_ALLOWED_HOSTS setting.",
                status=403,
                content_type="text/plain",
            )
    if sec_chk_rules:
        pass
    if not headers:
        headers, access_token = get_headers(request, url, raw_url, allowed_hosts=allowed_hosts)
    if not access_token:
        auth_header = None
        if "Authorization" in headers:
            auth_header = headers["Authorization"]
        elif "HTTP_AUTHORIZATION" in request.META:
            auth_header = request.META.get("HTTP_AUTHORIZATION", request.META.get("HTTP_AUTHORIZATION2"))
        if auth_header:
            access_token = get_token_from_auth_header(auth_header, create_if_not_exists=True)
    user = get_auth_user(access_token)
    parsed = urlparse(raw_url)
    parsed._replace(path=locator.encode("utf8"))
    if parsed.netloc == site_url.netloc and scheme != site_url.scheme:
        parsed = parsed._replace(scheme=site_url.scheme)
    _url = parsed.geturl()
    _url = URL.from_text(_url).normalize().to_text()
    if request.method == "GET" and access_token and "access_token" not in _url:
        query_separator = "&" if "?" in _url else "?"
        _url = f"{_url}{query_separator}access_token={access_token}"
    _data = request.body.decode("utf-8")
    if check_ogc_backend(geoserver.BACKEND_PACKAGE):
        from geonode.geoserver.helpers import ogc_server_settings
        _url = _url.replace(f"{settings.SITEURL}geoserver", ogc_server_settings.LOCATION.rstrip("/"))
        _data = _data.replace(f"{settings.SITEURL}geoserver", ogc_server_settings.LOCATION.rstrip("/"))
    response, content = http_client.request(
        _url, method=request.method, data=_data.encode("utf-8"), headers=headers, timeout=timeout, user=user
    )
    if response is None:
        return HttpResponse(content=content, reason=content, status=500)
    content = response.content or response.reason
    status = response.status_code
    response_headers = response.headers
    content_type = response.headers.get("Content-Type")
    if status >= 400:
        _response = HttpResponse(content=content, reason=content, status=status, content_type=content_type)
        return fetch_response_headers(_response, response_headers)
    if content and content_type and content_type == "gzip":
        buf = io.BytesIO(content)
        with gzip.GzipFile(fileobj=buf) as f:
            content = f.read()
        buf.close()
    PLAIN_CONTENT_TYPES = ["text", "plain", "html", "json", "xml", "gml"]
    for _ct in PLAIN_CONTENT_TYPES:
        if content_type and _ct in content_type and not isinstance(content, str):
            try:
                content = content.decode()
                break
            except Exception:
                pass
    if response and response_callback:
        kwargs = {} if not kwargs else kwargs
        kwargs.update(
            {
                "response": response,
                "content": content,
                "status": status,
                "response_headers": response_headers,
                "content_type": content_type,
            }
        )
        return response_callback(**kwargs)
    else:
        if status and status in (301, 302, 303, 307):
            _response = HttpResponse(
                (
                    f"This proxy does not support redirects. The server in '{url}' "
                    f"asked for a redirect to '{response.getheader('Location')}'"
                ),
                status=status,
                content_type=content_type,
            )
            _response["Location"] = response.getheader("Location")
            return fetch_response_headers(_response, response_headers)
        else:
            def _get_message(text):
                _s = text
                if isinstance(text, bytes):
                    _s = text.decode("utf-8", "replace")
                try:
                    found = re.search("<b>Message</b>(.+?)</p>", _s).group(1).strip()
                except Exception:
                    found = _s
                return found
            _response = HttpResponse(
                content=content,
                reason=_get_message(content) if status not in (200, 201) else None,
                status=status,
                content_type=content_type,
            )
            return fetch_response_headers(_response, response_headers)
logger = logging.getLogger(__name__)
def gs_slurp(
    ignore_errors=False,
    verbosity=1,
    console=None,
    owner=None,
    workspace=None,
    store=None,
    filter=None,
    skip_unadvertised=False,
    skip_geonode_registered=False,
    remove_deleted=False,
    permissions=None,
    execute_signals=False,
):
    """Configure the layers available in GeoServer in GeoNode.
    It returns a list of dictionaries with the name of the layer,
    the result of the operation and the errors and traceback if it failed.
    """
    from geonode.resource.manager import resource_manager
    if console is None:
        console = open(os.devnull, "w")
    if verbosity > 0:
        print("Inspecting the available layers in GeoServer ...", file=console)
    cat = gs_catalog
    if workspace is not None and workspace:
        workspace = cat.get_workspace(workspace)
        if workspace is None:
            resources = []
        else:
            if store is not None:
                store = get_store(cat, store, workspace=workspace)
                if store is None:
                    resources = []
                else:
                    resources = cat.get_resources(stores=[store])
            else:
                resources = cat.get_resources(workspaces=[workspace])
    elif store is not None:
        store = get_store(cat, store)
        resources = cat.get_resources(stores=[store])
    else:
        resources = cat.get_resources()
    if remove_deleted:
        resources_for_delete_compare = resources[:]
        workspace_for_delete_compare = workspace
        try:
            resources_for_delete_compare = [k for k in resources_for_delete_compare if k.enabled in {"true", True}]
            if skip_unadvertised:
                resources_for_delete_compare = [
                    k for k in resources_for_delete_compare if k.advertised in {"true", True}
                ]
        except Exception:
            if ignore_errors:
                pass
            else:
                raise
    if filter:
        resources = [k for k in resources if filter in k.name]
    _resources = []
    for k in resources:
        try:
            if k.enabled in {"true", True}:
                _resources.append(k)
        except Exception:
            if ignore_errors:
                continue
            else:
                raise
    resources = _resources
    if skip_unadvertised:
        try:
            resources = [k for k in resources if k.advertised in {"true", True}]
        except Exception:
            if ignore_errors:
                pass
            else:
                raise
    dataset_names = Dataset.objects.values_list("alternate", flat=True)
    if skip_geonode_registered:
        try:
            resources = [k for k in resources if f"{k.workspace.name}:{k.name}" not in dataset_names]
        except Exception:
            if ignore_errors:
                pass
            else:
                raise
    number = len(resources)
    if verbosity > 0:
        msg = "Found %d layers, starting processing" % number
        print(msg, file=console)
    output = {
        "stats": {
            "failed": 0,
            "updated": 0,
            "created": 0,
            "deleted": 0,
        },
        "layers": [],
        "deleted_datasets": [],
    }
    start = datetime.datetime.now(timezone.get_current_timezone())
    for i, resource in enumerate(resources):
        name = resource.name
        the_store = resource.store
        workspace = the_store.workspace
        layer = None
        try:
            created = False
            layer = Dataset.objects.filter(name=name, workspace=workspace.name).first()
            if not layer:
                layer = resource_manager.create(
                    str(uuid.uuid4()),
                    resource_type=Dataset,
                    defaults=dict(
                        name=name,
                        workspace=workspace.name,
                        store=the_store.name,
                        subtype=get_dataset_storetype(the_store.resource_type),
                        alternate=f"{workspace.name}:{resource.name}",
                        title=resource.title or _("No title provided"),
                        abstract=resource.abstract or _("No abstract provided"),
                        owner=owner,
                    ),
                )
                created = True
            layer.set_processing_state("RUNNING")
            bbox = resource.native_bbox
            ll_bbox = resource.latlon_bbox
            try:
                layer.set_bbox_polygon([bbox[0], bbox[2], bbox[1], bbox[3]], resource.projection)
            except GeoNodeException as e:
                if not ll_bbox:
                    raise
                else:
                    logger.exception(e)
                    layer.srid = "EPSG:4326"
            layer.set_ll_bbox_polygon([ll_bbox[0], ll_bbox[2], ll_bbox[1], ll_bbox[3]])
            perm_spec = json.loads(_perms_info_json(layer))
            resource_manager.set_permissions(layer.uuid, permissions=perm_spec)
            set_attributes_from_geoserver(layer, overwrite=True)
            resource_manager.update(layer.uuid, instance=layer, notify=execute_signals)
            resource_manager.set_thumbnail(layer.uuid, overwrite=True, check_bbox=False)
        except Exception as e:
            if layer:
                layer.set_processing_state("FAILED")
            if ignore_errors:
                status = "failed"
                exception_type, error, traceback = sys.exc_info()
            else:
                if verbosity > 0:
                    msg = "Stopping process because --ignore-errors was not set and an error was found."
                    print(msg, file=sys.stderr)
                raise Exception(f"Failed to process {resource.name}") from e
        if layer is None:
            if ignore_errors:
                status = "failed"
                exception_type, error, traceback = sys.exc_info()
            else:
                if verbosity > 0:
                    msg = "Stopping process because --ignore-errors was not set and an error was found."
                    print(msg, file=sys.stderr)
                raise Exception(f"Failed to process {resource.name}")
        else:
            if created:
                if not permissions:
                    layer.set_default_permissions()
                else:
                    layer.set_permissions(permissions)
                status = "created"
                output["stats"]["created"] += 1
            else:
                status = "updated"
                output["stats"]["updated"] += 1
        msg = f"[{status}] Dataset {name} ({(i + 1)}/{number})"
        info = {"name": name, "status": status}
        if status == "failed":
            output["stats"]["failed"] += 1
            info["traceback"] = traceback
            info["exception_type"] = exception_type
            info["error"] = error
        output["layers"].append(info)
        if verbosity > 0:
            print(msg, file=console)
    if remove_deleted:
        q = Dataset.objects.filter()
        if workspace_for_delete_compare is not None:
            if isinstance(workspace_for_delete_compare, Workspace):
                q = q.filter(workspace__exact=workspace_for_delete_compare.name)
            else:
                q = q.filter(workspace__exact=workspace_for_delete_compare)
        if store is not None:
            if isinstance(store, CoverageStore) or isinstance(store, DataStore):
                q = q.filter(store__exact=store.name)
            else:
                q = q.filter(store__exact=store)
        logger.debug("Executing 'remove_deleted' logic")
        logger.debug("GeoNode Layers Found:")
        deleted_datasets = []
        for layer in q:
            logger.debug(
                "GeoNode Dataset info: name: %s, workspace: %s, store: %s", layer.name, layer.workspace, layer.store
            )
            dataset_found_in_geoserver = False
            for resource in resources_for_delete_compare:
                if layer.name == resource.name:
                    if layer.workspace == resource.workspace.name and layer.store == resource.store.name:
                        logger.debug(
                            "Matches GeoServer layer: name: %s, workspace: %s, store: %s",
                            resource.name,
                            resource.workspace.name,
                            resource.store.name,
                        )
                        dataset_found_in_geoserver = True
            if not dataset_found_in_geoserver:
                logger.debug("----- Dataset %s not matched, marked for deletion ---------------", layer.name)
                deleted_datasets.append(layer)
        number_deleted = len(deleted_datasets)
        if verbosity > 0:
            msg = (
                "\nFound %d layers to delete, starting processing" % number_deleted
                if number_deleted > 0
                else "\nFound %d layers to delete" % number_deleted
            )
            print(msg, file=console)
        for i, layer in enumerate(deleted_datasets):
            logger.debug(
                "GeoNode Dataset to delete: name: %s, workspace: %s, store: %s",
                layer.name,
                layer.workspace,
                layer.store,
            )
            try:
                ct = ContentType.objects.get_for_model(layer)
                OverallRating.objects.filter(content_type=ct, object_id=layer.id).delete()
                layer.keywords.clear()
                layer.delete()
                output["stats"]["deleted"] += 1
                status = "delete_succeeded"
            except Exception:
                status = "delete_failed"
            msg = f"[{status}] Dataset {layer.name} ({(i + 1)}/{number_deleted})"
            info = {"name": layer.name, "status": status}
            if status == "delete_failed":
                exception_type, error, traceback = sys.exc_info()
                info["traceback"] = traceback
                info["exception_type"] = exception_type
                info["error"] = error
            output["deleted_datasets"].append(info)
            if verbosity > 0:
                print(msg, file=console)
    finish = datetime.datetime.now(timezone.get_current_timezone())
    td = finish - start
    output["stats"]["duration_sec"] = td.microseconds / 1000000 + td.seconds + td.days * 24 * 3600
    return output
