                    sys.exit(1)
            if opts.downloadcomps:
                wanted_types = ['group']
            if opts.downloadmd:
                wanted_types = repo.repoXML.fileTypes()
            for ftype in repo.repoXML.fileTypes():
                if ftype in ['primary', 'primary_db', 'filelists',
                             'filelists_db', 'other', 'other_db']:
                    continue
