def parse_regular_functions(
    regular_functions, sigs, external_interfaces, global_ctx, default_function, init_function
):
    func_types = [i._metadata["type"] for i in global_ctx._defs]
    mutabilities = [i.mutability for i in func_types if i.visibility == FunctionVisibility.EXTERNAL]
    has_payable = any(i == StateMutability.PAYABLE for i in mutabilities)
    has_nonpayable = any(i != StateMutability.PAYABLE for i in mutabilities)
    is_default_payable = (
        default_function is not None
        and default_function._metadata["type"].mutability == StateMutability.PAYABLE
    )
    check_per_function = is_default_payable and has_nonpayable
    payable_funcs = []
    nonpayable_funcs = []
    internal_funcs = []
    add_gas = 0
    for func_node in regular_functions:
        func_type = func_node._metadata["type"]
        func_ir, frame_start, frame_size = generate_ir_for_function(
            func_node, {**{"self": sigs}, **external_interfaces}, global_ctx, check_per_function
        )
        if func_type.visibility == FunctionVisibility.INTERNAL:
            internal_funcs.append(func_ir)
        elif func_type.mutability == StateMutability.PAYABLE:
            add_gas += 30
            payable_funcs.append(func_ir)
        else:
            add_gas += 30
            nonpayable_funcs.append(func_ir)
        func_ir.total_gas += add_gas
        sig = FunctionSignature.from_definition(func_node, external_interfaces, global_ctx._structs)
        sig.gas = func_ir.total_gas
        sig.frame_start = frame_start
        sig.frame_size = frame_size
        sigs[sig.name] = sig
    if default_function:
        fallback_ir, _frame_start, _frame_size = generate_ir_for_function(
            default_function,
            {**{"self": sigs}, **external_interfaces},
            global_ctx,
            check_per_function or not regular_functions,
        )
    else:
        fallback_ir = IRnode.from_list(["revert", 0, 0], typ=None, annotation="Default function")
    if check_per_function:
        external_seq = ["seq"] + payable_funcs + nonpayable_funcs
    else:
        external_seq = ["seq"]
        if has_payable:
            external_seq += payable_funcs
        if has_nonpayable:
            external_seq.append(["assert", ["iszero", "callvalue"]])
            external_seq += nonpayable_funcs
    close_selector_section = ["goto", "fallback"]
    runtime = [
        "seq",
        ["if", ["lt", "calldatasize", 4], ["goto", "fallback"]],
        ["with", "_calldata_method_id", shr(224, ["calldataload", 0]), external_seq],
        close_selector_section,
        ["label", "fallback", ["var_list"], fallback_ir],
    ]
    runtime.extend(internal_funcs)
    return runtime
def parse_tree_to_ir(global_ctx: GlobalContext) -> Tuple[IRnode, IRnode, FunctionSignatures]:
        runtime = parse_regular_functions(
            regular_functions,
            sigs,
            external_interfaces,
            global_ctx,
            default_function,
            init_func_ir,
        )
def generate_ir_for_function(
    code: vy_ast.FunctionDef,
    sigs: Dict[str, Dict[str, FunctionSignature]],
    global_ctx: GlobalContext,
    check_nonpayable: bool,
) -> Tuple[IRnode, int, int]:
    """
    Parse a function and produce IR code for the function, includes:
        - Signature method if statement
        - Argument handling
        - Clamping and copying of arguments
        - Function body
    """
    sig = FunctionSignature.from_definition(
        code,
        sigs=sigs,
        custom_structs=global_ctx._structs,
    )
    check_single_exit(code)
    def _run_pass(memory_allocator=None):
        if memory_allocator is None:
            memory_allocator = MemoryAllocator()
        nonlocal sig
        sig = copy.deepcopy(sig)
        context = Context(
            vars_=None,
            global_ctx=global_ctx,
            sigs=sigs,
            memory_allocator=memory_allocator,
            return_type=sig.return_type,
            constancy=Constancy.Constant
            if sig.mutability in ("view", "pure")
            else Constancy.Mutable,
            is_payable=sig.mutability == "payable",
            is_internal=sig.internal,
            sig=sig,
        )
        if sig.internal:
            o = generate_ir_for_internal_function(code, sig, context)
        else:
            o = generate_ir_for_external_function(code, sig, context, check_nonpayable)
        o.source_pos = getpos(code)
        return o, context
    _, context = _run_pass(memory_allocator=None)
    allocate_start = context.max_callee_frame_size
    allocate_start += MemoryPositions.RESERVED_MEMORY
    o, context = _run_pass(memory_allocator=MemoryAllocator(allocate_start))
    frame_size = context.memory_allocator.size_of_mem - MemoryPositions.RESERVED_MEMORY
    if not sig.internal:
        o.total_gas = o.gas + calc_mem_gas(frame_size)
    else:
        o.total_gas = o.gas
    o.context = context
    o.func_name = sig.name
    return o, allocate_start, frame_size
@_input_types("int", "bytes_m", "decimal", "bytes", "address", "bool")
def to_int(expr, arg, out_typ):
    int_info = out_typ._int_info
    assert int_info.bits % 8 == 0
    _check_bytes(expr, arg, out_typ, 32)
    if isinstance(expr, vy_ast.Constant):
        return _literal_int(expr, out_typ)
    elif isinstance(arg.typ, ByteArrayType):
        arg_typ = arg.typ
        arg = _bytes_to_num(arg, out_typ, signed=int_info.is_signed)
        if arg_typ.maxlen * 8 > int_info.bits:
            arg = int_clamp(arg, int_info.bits, signed=int_info.is_signed)
    elif is_bytes_m_type(arg.typ):
        arg_info = arg.typ._bytes_info
        arg = _bytes_to_num(arg, out_typ, signed=int_info.is_signed)
        if arg_info.m_bits > int_info.bits:
            arg = int_clamp(arg, int_info.bits, signed=int_info.is_signed)
    elif is_decimal_type(arg.typ):
        arg_info = arg.typ._decimal_info
        arg = _fixed_to_int(arg, out_typ)
        arg = _num_clamp(arg, int_info, arg_info)
    elif is_integer_type(arg.typ):
        arg_info = arg.typ._int_info
        arg = _num_clamp(arg, int_info, arg_info)
    elif is_base_type(arg.typ, "address"):
        if int_info.is_signed:
            _FAIL(arg.typ, out_typ, expr)
        if int_info.bits > 160:
            arg = int_clamp(arg, 160, signed=False)
    return IRnode.from_list(arg, typ=out_typ)
