            "haystack"
        ) as (b2, right):
            if right.value == "multi":
                tmp_list = IRnode.from_list(
                    self.context.new_internal_variable(right.typ), typ=right.typ, location=MEMORY
                )
                ret.append(make_setter(tmp_list, right))
                right = tmp_list
