    def init_server_conn(self, msg_obj):
        try:
            self.server_socket = server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            server_socket.setblocking(0)
            self.set_server_socket_keepalive(server_socket)
            if self.bindip:
                server_socket.bind((self.bindip, 0))
            elif self.interface:
                self.bind_to_network_interface(server_socket, self.interface)
            server_socket.connect_ex(msg_obj.addr)
            self.selector.register(server_socket, selectors.EVENT_READ | selectors.EVENT_WRITE)
            self._connsinprogress[server_socket] = PeerConnectionInProgress(server_socket, msg_obj)
            self._numsockets += 1
        except socket.error as err:
            self._callback_msgs.append(ConnectError(msg_obj, err))
            server_socket.close()
            self.server_disconnect()
    def process_server_output(self, msg_obj):
        if self.server_socket not in self._conns:
            log.add_conn("Can't send the message over the closed connection: %(type)s %(msg_obj)s", {
                'type': msg_obj.__class__,
                'msg_obj': vars(msg_obj)
            })
            return
        msg = self.pack_network_message(msg_obj)
        if msg is None:
            return
        conn_obj = self._conns[self.server_socket]
        conn_obj.obuf.extend(UINT_PACK(len(msg) + 4))
        conn_obj.obuf.extend(UINT_PACK(self.servercodes[msg_obj.__class__]))
        conn_obj.obuf.extend(msg)
        self.modify_connection_events(conn_obj, selectors.EVENT_READ | selectors.EVENT_WRITE)
    def process_file_input(self, conn, msg_buffer):
        """ We have a "F" connection (filetransfer), peer has sent us
        something, this function retrieves messages
        from the msg_buffer, creates message objects and returns them
        and the rest of the msg_buffer.
        """
        if conn.filereq is None:
            msgsize = 4
            msg = self.unpack_network_message(FileRequest, msg_buffer[:msgsize], msgsize, "file", conn.conn)
            if msg is not None and msg.req is not None:
                self._callback_msgs.append(msg)
                conn.filereq = msg
            msg_buffer = msg_buffer[msgsize:]
        elif conn.filedown is not None:
            leftbytes = conn.bytestoread - conn.filereadbytes
            addedbytes = msg_buffer[:leftbytes]
            if leftbytes > 0:
                try:
                    conn.filedown.file.write(addedbytes)
                except IOError as strerror:
                    self._callback_msgs.append(FileError(conn, conn.filedown.file, strerror))
                    self._callback_msgs.append(ConnClose(conn.conn, conn.addr))
                    self.close_connection(self._conns, conn.conn)
                except ValueError:
                    pass
            addedbyteslen = len(addedbytes)
            curtime = time.time()
            finished = ((leftbytes - addedbyteslen) == 0)
            if finished or (curtime - conn.lastcallback) > 1:
                self._callback_msgs.append(DownloadFile(conn.conn, conn.filedown.file))
                conn.lastcallback = curtime
            if finished:
                self._callback_msgs.append(ConnClose(conn.conn, conn.addr))
                self.close_connection(self._conns, conn.conn)
            conn.filereadbytes += addedbyteslen
            msg_buffer = msg_buffer[leftbytes:]
        elif conn.fileupl is not None and conn.fileupl.offset is None:
            msgsize = 8
            msg = self.unpack_network_message(FileOffset, msg_buffer[:msgsize], msgsize, "file", conn)
            if msg is not None and msg.offset is not None:
                try:
                    conn.fileupl.file.seek(msg.offset)
                    self.modify_connection_events(conn, selectors.EVENT_READ | selectors.EVENT_WRITE)
                except IOError as strerror:
                    self._callback_msgs.append(FileError(conn, conn.fileupl.file, strerror))
                    self._callback_msgs.append(ConnClose(conn.conn, conn.addr))
                    self.close_connection(self._conns, conn.conn)
                except ValueError:
                    pass
                conn.fileupl.offset = msg.offset
                self._callback_msgs.append(conn.fileupl)
            msg_buffer = msg_buffer[msgsize:]
        conn.ibuf = msg_buffer
    def process_distrib_output(self, msg_obj):
        if msg_obj.conn not in self._conns:
            log.add_conn("Can't send the message over the closed connection: %(type)s %(msg_obj)s", {
                'type': msg_obj.__class__,
                'msg_obj': vars(msg_obj)
            })
            return
        msg = self.pack_network_message(msg_obj)
        if msg is None:
            return
        conn_obj = self._conns[msg_obj.conn]
        conn_obj.obuf.extend(UINT_PACK(len(msg) + 1))
        conn_obj.obuf.extend(bytes([self.distribcodes[msg_obj.__class__]]))
        conn_obj.obuf.extend(msg)
        self.modify_connection_events(conn_obj, selectors.EVENT_READ | selectors.EVENT_WRITE)
class ChatEntry:
    def on_enter(self, *_args):
        if not self.frame.np.logged_in:
            return
        text = self.entry.get_text()
        if not text:
            return
        if is_alias(text):
            alias_text = get_alias(text)
            if not alias_text:
                log.add(_('Alias "%s" returned nothing'), text)
                return
            text = alias_text
        is_double_slash_cmd = text.startswith("//")
        is_single_slash_cmd = (text.startswith("/") and not is_double_slash_cmd)
        if not is_single_slash_cmd or text.startswith("/me"):
            self.entry.set_text("")
            if is_double_slash_cmd:
                text = text[1:]
            self.send_message(self.entity, text)
            return
        cmd_split = text.split(maxsplit=1)
        cmd = cmd_split[0]
        if cmd + " " not in self.command_list:
            log.add(_("Command %s is not recognized"), cmd)
            return
        self.entry.set_text("")
        if len(cmd_split) == 2:
            args = arg_self = cmd_split[1]
        else:
            args = ""
            arg_self = "" if self.is_chatroom else self.entity
        if cmd in ("/alias", "/al"):
            parent = self.frame.np.chatrooms if self.is_chatroom else self.frame.np.privatechats
            parent.echo_message(self.entity, add_alias(args))
            if config.sections["words"]["aliases"]:
                self.frame.update_completions()
        elif cmd in ("/unalias", "/un"):
            parent = self.frame.np.chatrooms if self.is_chatroom else self.frame.np.privatechats
            parent.echo_message(self.entity, unalias(args))
            if config.sections["words"]["aliases"]:
                self.frame.update_completions()
        elif cmd in ("/w", "/whois", "/info"):
            if arg_self:
                self.frame.np.userinfo.request_user_info(arg_self)
                self.frame.change_main_page("userinfo")
        elif cmd in ("/b", "/browse"):
            if arg_self:
                self.frame.np.userbrowse.browse_user(arg_self)
                self.frame.change_main_page("userbrowse")
        elif cmd == "/ip":
            if arg_self:
                self.frame.np.request_ip_address(arg_self)
        elif cmd == "/pm":
            if args:
                self.frame.np.privatechats.show_user(args)
                self.frame.change_main_page("private")
        elif cmd in ("/m", "/msg"):
            if args:
                args_split = args.split(" ", maxsplit=1)
                user = args_split[0]
                msg = None
                if len(args_split) == 2:
                    msg = args_split[1]
                if msg:
                    self.frame.np.privatechats.show_user(user)
                    self.frame.np.privatechats.send_message(user, msg)
                    self.frame.change_main_page("private")
        elif cmd in ("/s", "/search"):
            if args:
                self.frame.np.search.do_search(args, "global")
                self.frame.change_main_page("search")
        elif cmd in ("/us", "/usearch"):
            args_split = args.split(" ", maxsplit=1)
            if len(args_split) == 2:
                self.frame.np.search.do_search(args_split[1], "user", user=args_split[0])
                self.frame.change_main_page("search")
        elif cmd in ("/rs", "/rsearch"):
            if args:
                self.frame.np.search.do_search(args, "rooms")
                self.frame.change_main_page("search")
        elif cmd in ("/bs", "/bsearch"):
            if args:
                self.frame.np.search.do_search(args, "buddies")
                self.frame.change_main_page("search")
        elif cmd in ("/j", "/join"):
            if args:
                self.frame.np.queue.append(slskmessages.JoinRoom(args))
        elif cmd in ("/l", "/leave", "/p", "/part"):
            if args:
                self.frame.np.queue.append(slskmessages.LeaveRoom(args))
            else:
                self.frame.np.queue.append(slskmessages.LeaveRoom(self.entity))
        elif cmd in ("/ad", "/add", "/buddy"):
            if args:
                self.frame.np.userlist.add_user(args)
        elif cmd in ("/rem", "/unbuddy"):
            if args:
                self.frame.np.userlist.remove_user(args)
        elif cmd == "/ban":
            if args:
                self.frame.np.network_filter.ban_user(args)
        elif cmd == "/ignore":
            if args:
                self.frame.np.network_filter.ignore_user(args)
        elif cmd == "/ignoreip":
            if args:
                self.frame.np.network_filter.ignore_ip(args)
        elif cmd == "/unban":
            if args:
                self.frame.np.network_filter.unban_user(args)
        elif cmd == "/unignore":
            if args:
                self.frame.np.network_filter.unignore_user(args)
        elif cmd == "/ctcpversion":
            if arg_self:
                self.frame.np.privatechats.show_user(arg_self)
                self.frame.np.privatechats.send_message(arg_self, self.frame.np.privatechats.CTCP_VERSION)
        elif cmd in ("/clear", "/cl"):
            if self.is_chatroom:
                parent = self.frame.chatrooms.pages[self.entity]
            else:
                parent = self.frame.privatechat.pages[self.entity]
            parent.chat_textview.clear()
        elif cmd in ("/a", "/away"):
            self.frame.on_away()
        elif cmd in ("/q", "/quit", "/exit"):
            self.frame.np.quit()
        elif cmd in ("/c", "/close"):
            self.frame.privatechat.pages[self.entity].on_close()
        elif cmd == "/now":
            self.frame.np.now_playing.display_now_playing(
                callback=lambda np_message: self.send_message(self.entity, np_message))
        elif cmd == "/rescan":
            self.frame.np.shares.rescan_shares()
        elif cmd == "/toggle":
            if args:
                self.frame.np.pluginhandler.toggle_plugin(args)
        elif self.is_chatroom:
            self.frame.np.pluginhandler.trigger_public_command_event(self.entity, cmd[1:], args)
        elif not self.is_chatroom:
            self.frame.np.pluginhandler.trigger_private_command_event(self.entity, cmd[1:], args)
