def open_uri(uri):
    """ Open a URI in an external (web) browser. The given argument has
    to be a properly formed URI including the scheme (fe. HTTP). """
    protocol = uri[:uri.find(":")]
    protocol_handlers = config.sections["urls"]["protocols"]
    if protocol in protocol_handlers and protocol_handlers[protocol]:
        try:
            execute_command(protocol_handlers[protocol], uri)
            return True
        except RuntimeError as error:
            log.add(error)
    if protocol == "slsk":
        OPEN_SOULSEEK_URL(uri.strip())
        return True
    try:
        if not webbrowser.open(uri):
            raise webbrowser.Error("no known URL provider available")
        return True
    except Exception as error:
        log.add(_("Failed to open URL: %s"), error)
    return False
def human_length(seconds):
    minutes, seconds = divmod(seconds, 60)
    hours, minutes = divmod(minutes, 60)
    days, hours = divmod(hours, 24)
    if days > 0:
        ret = '%i:%02i:%02i:%02i' % (days, hours, minutes, seconds)
    elif hours > 0:
        ret = '%i:%02i:%02i' % (hours, minutes, seconds)
    else:
        ret = '%i:%02i' % (minutes, seconds)
    return ret
def initialise_columns(frame, treeview_name, treeview, *args):
    i = 0
    cols = OrderedDict()
    column_config = None
    for column_id, title, width, column_type, extra in args:
        if treeview_name:
            try:
                column_config = config.sections["columns"][treeview_name[0]][treeview_name[1]]
            except KeyError:
                column_config = config.sections["columns"][treeview_name]
            try:
                width = column_config[column_id]["width"]
            except Exception:
                pass
        if not isinstance(width, int):
            width = 0
        if Gtk.get_major_version() == 4:
            height_padding = 4
        else:
            height_padding = 3
        if column_type == "text":
            renderer = Gtk.CellRendererText()
            renderer.set_padding(10, height_padding)
            column = Gtk.TreeViewColumn(column_id, renderer, text=i)
        elif column_type == "center":
            renderer = Gtk.CellRendererText()
            renderer.set_property("xalign", 0.5)
            column = Gtk.TreeViewColumn(column_id, renderer, text=i)
        elif column_type == "number":
            renderer = Gtk.CellRendererText()
            renderer.set_property("xalign", 0.9)
            column = Gtk.TreeViewColumn(column_id, renderer, text=i)
            column.set_alignment(0.9)
        elif column_type == "edit":
            renderer = Gtk.CellRendererText()
            renderer.set_padding(10, height_padding)
            renderer.set_property('editable', True)
            column = Gtk.TreeViewColumn(column_id, renderer, text=i)
        elif column_type == "combo":
            renderer = Gtk.CellRendererCombo()
            renderer.set_padding(10, height_padding)
            renderer.set_property('text-column', 0)
            renderer.set_property('editable', True)
            column = Gtk.TreeViewColumn(column_id, renderer, text=i)
        elif column_type == "progress":
            renderer = Gtk.CellRendererProgress()
            column = Gtk.TreeViewColumn(column_id, renderer, value=i)
        elif column_type == "toggle":
            renderer = Gtk.CellRendererToggle()
            column = Gtk.TreeViewColumn(column_id, renderer, active=i)
            renderer.set_property("xalign", 0.5)
        else:
            renderer = Gtk.CellRendererPixbuf()
            column = Gtk.TreeViewColumn(column_id, renderer, gicon=i)
            if column_id == "country":
                if Gtk.get_major_version() == 4:
                    renderer.set_property("icon-size", Gtk.IconSize.NORMAL)
                else:
                    renderer.set_property("stock-size", 0)
        if width == -1:
            column.set_resizable(False)
            column.set_expand(True)
            column.set_sizing(Gtk.TreeViewColumnSizing.AUTOSIZE)
        else:
            column.set_resizable(True)
            if width == 0:
                column.set_sizing(Gtk.TreeViewColumnSizing.GROW_ONLY)
            else:
                column.set_sizing(Gtk.TreeViewColumnSizing.FIXED)
                column.set_fixed_width(width)
            column.set_min_width(0)
        if isinstance(extra, int):
            column.add_attribute(renderer, "foreground", extra)
        elif isinstance(extra, tuple):
            weight, underline = extra
            column.add_attribute(renderer, "weight", weight)
            column.add_attribute(renderer, "underline", underline)
        column.set_reorderable(True)
        column.set_min_width(20)
        column.set_widget(Gtk.Label.new(title))
        column.get_widget().set_margin_start(5)
        column.get_widget().show()
        cols[column_id] = column
        i += 1
    append_columns(treeview, cols, column_config)
    hide_columns(treeview, cols, column_config)
    treeview.connect("columns-changed", set_last_column_autosize)
    treeview.emit("columns-changed")
    setup_accelerator("<Primary>c", treeview, on_copy_cell_data_accelerator)
    treeview.column_menu = PopupMenu(frame, treeview, callback=press_header, connect_events=False)
    if Gtk.get_major_version() == 4:
        treeview.set_rubber_banding(False)
    return cols
