class NicotineCore:
    def quit(self, signal_type=None, _frame=None):
        log.add(_("Quitting Nicotine+ %(version)s, %(status)s…"), {
            "version": config.version,
            "status": _("terminating") if signal_type == signal.SIGTERM else _("application closing")
