class UnicornTemplateResponse(TemplateResponse):
    @timed
    def render(self):
        response = super().render()
        if not self.component or not self.component.component_id:
            return response
        content = response.content.decode("utf-8")
        frontend_context_variables = self.component.get_frontend_context_variables()
        frontend_context_variables_dict = orjson.loads(frontend_context_variables)
        checksum = generate_checksum(orjson.dumps(frontend_context_variables_dict))
        soup = BeautifulSoup(content, features="html.parser")
        root_element = get_root_element(soup)
        root_element["unicorn:id"] = self.component.component_id
        root_element["unicorn:name"] = self.component.component_name
        root_element["unicorn:key"] = self.component.component_key
        root_element["unicorn:checksum"] = checksum
        hash = generate_checksum(UnicornTemplateResponse._desoupify(soup))
        if self.init_js:
            init = {
                "id": self.component.component_id,
                "name": self.component.component_name,
                "key": self.component.component_key,
                "data": orjson.loads(frontend_context_variables),
                "calls": self.component.calls,
                "hash": hash,
            }
            init = orjson.dumps(init).decode("utf-8")
            json_element_id = f"unicorn:data:{self.component.component_id}"
            init_script = f"Unicorn.componentInit(JSON.parse(document.getElementById('{json_element_id}').textContent));"
            json_tag = soup.new_tag("script")
            json_tag["type"] = "application/json"
            json_tag["id"] = json_element_id
            json_tag.string = sanitize_html(init)
            if self.component.parent:
                self.component._init_script = init_script
                self.component._json_tag = json_tag
            else:
                json_tags = []
                json_tags.append(json_tag)
                for child in self.component.children:
                    init_script = f"{init_script} {child._init_script}"
                    json_tags.append(child._json_tag)
                script_tag = soup.new_tag("script")
                script_tag["type"] = "module"
                script_tag.string = f"if (typeof Unicorn === 'undefined') {{ console.error('Unicorn is missing. Do you need {{% load unicorn %}} or {{% unicorn_scripts %}}?') }} else {{ {init_script} }}"
                root_element.insert_after(script_tag)
                for t in json_tags:
                    root_element.insert_after(t)
        rendered_template = UnicornTemplateResponse._desoupify(soup)
        self.component.rendered(rendered_template)
        response.content = rendered_template
        return response
def get_root_element(soup: BeautifulSoup) -> Tag:
    """
    Gets the first tag element.
    Returns:
        BeautifulSoup tag element.
        Raises an Exception if an element cannot be found.
    """
    for element in soup.contents:
        if isinstance(element, Tag) and element.name:
            return element
    raise Exception("No root element found")
def _fix_floats(current: Dict, data: Dict = None, paths: List = []) -> None:
    """
    Recursively change any Python floats to a string so that JavaScript
    won't convert the float to an integer when deserializing.
    Params:
        current: Dictionary in which to check for and fix floats.
    """
    if data is None:
        data = current
    if isinstance(current, dict):
        for key, val in current.items():
            paths.append(key)
            _fix_floats(val, data, paths=paths)
            paths.pop()
    elif isinstance(current, list):
        for (idx, item) in enumerate(current):
            paths.append(idx)
            _fix_floats(item, data, paths=paths)
            paths.pop()
    elif isinstance(current, float):
        _piece = data
        for (idx, path) in enumerate(paths):
            if idx == len(paths) - 1:
                _piece[path] = str(current)
            else:
                _piece = _piece[path]
def dumps(data: dict, fix_floats: bool = True) -> str:
    """
    Converts the passed-in dictionary to a string representation.
    Handles the following objects: dataclass, datetime, enum, float, int, numpy, str, uuid,
    Django Model, Django QuerySet, any object with `to_json` method.
    Args:
        param fix_floats: Whether any floats should be converted to strings. Defaults to `True`,
            but will be faster without it.
    Returns a string which deviates from `orjson.dumps`, but seems more useful.
    """
    serialized_data = orjson.dumps(data, default=_json_serializer)
    if fix_floats:
        return _dumps(serialized_data)
    return serialized_data.decode("utf-8")
def loads(str: str) -> dict:
    """
    Converts a string representation to dictionary.
    """
    try:
        return orjson.loads(str)
    except orjson.JSONDecodeError as e:
        raise JSONDecodeError from e
def convert_to_snake_case(s: str) -> str:
    return s.replace("-", "_")
def convert_to_pascal_case(s: str) -> str:
    s = convert_to_snake_case(s)
    return "".join(word.title() for word in s.split("_"))
def get_locations(component_name):
    locations = []
    if "." in component_name:
        component_name = component_name.replace("/", ".")
        class_name = component_name.split(".")[-1:][0]
        module_name = component_name.replace("." + class_name, "")
        locations.append((class_name, module_name))
        if component_name.endswith("View") or component_name.endswith("Component"):
            return locations
    component_name = component_name.replace("/", ".")
    class_name = convert_to_pascal_case(component_name)
    if "." in class_name:
        if class_name.split(".")[-1:]:
            class_name = class_name.split(".")[-1:][0]
    class_name = f"{class_name}View"
    module_name = convert_to_snake_case(component_name)
    unicorn_apps = get_setting("APPS", settings.INSTALLED_APPS)
    assert (
        isinstance(unicorn_apps, list)
        or isinstance(unicorn_apps, tuple)
        or isinstance(unicorn_apps, set)
    ), "APPS is expected to be a list, tuple or set"
    for app in unicorn_apps:
        if ".apps." in app:
            app_config_idx = app.rindex(".apps.")
            app = app[:app_config_idx]
        app_module_name = f"{app}.components.{module_name}"
        locations.append((class_name, app_module_name))
    return locations
@timed
def construct_component(
    component_class,
    component_id,
    component_name,
    component_key,
    parent,
    request,
    **kwargs,
):
    """
    Constructs a class instance.
    """
    component = component_class(
        component_id=component_id,
        component_name=component_name,
        component_key=component_key,
        parent=parent,
        request=request,
        **kwargs,
    )
    component.calls = []
    component.children = []
    component._children_set = False
    component.mount()
    component.hydrate()
    component.complete()
    component._validate_called = False
    return component
class UnicornView(TemplateView):
    @staticmethod
    @timed
    def create(
        component_id: str,
        component_name: str,
        component_key: str = "",
        parent: "UnicornView" = None,
        request: HttpRequest = None,
        use_cache=True,
        kwargs: Dict[str, Any] = {},
    ) -> "UnicornView":
        """
        Find and instantiate a component class based on `component_name`.
        Args:
            param component_id: Id of the component. Required.
            param component_name: Name of the component. Used to locate the correct `UnicornView`
                component class and template if necessary. Required.
            param component_key: Key of the component to allow multiple components of the same name
                to be differentiated. Optional.
            param parent: The parent component of the current component.
            param kwargs: Keyword arguments for the component passed in from the template. Defaults to `{}`.
        Returns:
            Instantiated `UnicornView` component.
            Raises `ComponentLoadError` if the component could not be loaded.
        """
        assert component_id, "Component id is required"
        assert component_name, "Component name is required"
        @timed
        def _get_component_class(
            module_name: str, class_name: str
        ) -> Type[UnicornView]:
            """
            Imports a component based on module and class name.
            """
            module = importlib.import_module(module_name)
            component_class = getattr(module, class_name)
            return component_class
        cache = caches[get_cache_alias()]
        component_cache_key = f"unicorn:component:{component_id}"
        cached_component = cache.get(component_cache_key)
        if cached_component:
            if cached_component.parent:
                cached_parent_component = cache.get(
                    cached_component.parent.component_cache_key
                )
                if cached_parent_component:
                    cached_component.parent = cached_parent_component
                    cached_component.parent.setup(request)
        else:
            cached_component = constructed_views_cache.get(component_id)
        if use_cache and cached_component:
            cached_component.setup(request)
            cached_component._validate_called = False
            cached_component.calls = []
            logger.debug(f"Retrieve {component_id} from constructed views cache")
            return cached_component
        if component_id in views_cache:
            (component_class, parent, kwargs) = views_cache[component_id]
            component = construct_component(
                component_class=component_class,
                component_id=component_id,
                component_name=component_name,
                component_key=component_key,
                parent=parent,
                request=request,
                **kwargs,
            )
            logger.debug(f"Retrieve {component_id} from views cache")
            return component
        locations = []
        if component_name in location_cache:
            locations.append(location_cache[component_name])
        else:
            locations = get_locations(component_name)
        last_exception: Union[
            Optional[ModuleNotFoundError], Optional[AttributeError]
        ] = None
        for (class_name, module_name) in locations:
            try:
                component_class = _get_component_class(module_name, class_name)
                component = construct_component(
                    component_class=component_class,
                    component_id=component_id,
                    component_name=component_name,
                    component_key=component_key,
                    parent=parent,
                    request=request,
                    **kwargs,
                )
                location_cache[component_name] = (class_name, module_name)
                views_cache[component_id] = (component_class, parent, kwargs)
                cacheable_component = None
                try:
                    cacheable_component = get_cacheable_component(component)
                except UnicornCacheError as e:
                    logger.warning(e)
                if cacheable_component:
                    if COMPONENTS_MODULE_CACHE_ENABLED:
                        constructed_views_cache[component_id] = cacheable_component
                    cache.set(
                        cacheable_component.component_cache_key, cacheable_component
                    )
                return component
            except ModuleNotFoundError as e:
                last_exception = e
            except AttributeError as e:
                last_exception = e
        raise ComponentLoadError(
            f"'{component_name}' component could not be loaded: {last_exception}"
        ) from last_exception
def handle(component_request: ComponentRequest, component: UnicornView, payload: Dict):
    call_method_name = payload.get("name", "")
    assert call_method_name, "Missing 'name' key for callMethod"
    (method_name, args, kwargs) = parse_call_method_name(call_method_name)
    return_data = Return(method_name, args, kwargs)
    setter_method = {}
    is_refresh_called = False
    is_reset_called = False
    validate_all_fields = False
    if "=" in call_method_name:
        try:
            setter_method = parse_kwarg(call_method_name, raise_if_unparseable=True)
        except InvalidKwarg:
            pass
    if setter_method:
        property_name = list(setter_method.keys())[0]
        property_value = setter_method[property_name]
        set_property_value(component, property_name, property_value)
        return_data = Return(property_name, [property_value])
    else:
        if method_name == "$refresh":
            component = UnicornView.create(
                component_id=component_request.id,
                component_name=component_request.name,
                request=component_request.request,
            )
            for (property_name, property_value,) in component_request.data.items():
                set_property_from_data(component, property_name, property_value)
            component.hydrate()
            is_refresh_called = True
        elif method_name == "$reset":
            component = UnicornView.create(
                component_id=component_request.id,
                component_name=component_request.name,
                request=component_request.request,
                use_cache=False,
            )
            component.errors = {}
            is_reset_called = True
        elif method_name == "$toggle":
            for property_name in args:
                property_value = _get_property_value(component, property_name)
                property_value = not property_value
                set_property_value(component, property_name, property_value)
        elif method_name == "$validate":
            validate_all_fields = True
        else:
            component.calling(method_name, args)
            return_data.value = _call_method_name(component, method_name, args, kwargs)
            component.called(method_name, args)
    return (
        component,
        is_refresh_called,
        is_reset_called,
        validate_all_fields,
        return_data,
    )
@timed
def _call_method_name(
    component: UnicornView, method_name: str, args: List[Any], kwargs: Dict[str, Any]
) -> Any:
    """
    Calls the method name with parameters.
    Args:
        param component: Component to call method on.
        param method_name: Method name to call.
        param args: List of arguments for the method.
        param kwargs: Dictionary of kwargs for the method.
    """
    if method_name is not None and hasattr(component, method_name):
        func = getattr(component, method_name)
        if len(args) == 1 or len(kwargs.keys()) == 1:
            arguments = get_method_arguments(func)
            type_hints = get_type_hints(func)
            for argument in arguments:
                if argument in type_hints:
                    if issubclass(type_hints[argument], Model):
                        DbModel = type_hints[argument]
                        key = "pk"
                        value = None
                        if args:
                            value = args.pop()
                        elif kwargs:
                            (key, value) = list(kwargs.items())[0]
                            del kwargs[key]
                        model = DbModel.objects.get(**{key: value})
                        args.append(model)
        if args and kwargs:
            return func(*args, **kwargs)
        elif args:
            return func(*args, **kwargs)
        elif kwargs:
            return func(**kwargs)
        else:
            return func()
def generate_checksum(data: Union[str, bytes]) -> str:
    """
    Generates a checksum for the passed-in data.
    """
    if isinstance(data, str):
        data_bytes = str.encode(data)
    else:
        data_bytes = data
    checksum = hmac.new(
        str.encode(settings.SECRET_KEY), data_bytes, digestmod="sha256",
    ).hexdigest()
    checksum = shortuuid.uuid(checksum)[:8]
    return checksum
def get_cacheable_component(
    component: "django_unicorn.views.UnicornView",
) -> "django_unicorn.views.UnicornView":
    """
    Converts a component into something that is cacheable/pickleable.
    """
    component.request = None
    if component.parent:
        component.parent = get_cacheable_component(component.parent)
    try:
        pickle.dumps(component)
    except (TypeError, AttributeError, NotImplementedError, pickle.PicklingError) as e:
        raise UnicornCacheError(
            f"Cannot cache component '{type(component)}' because it is not picklable: {type(e)}: {e}"
        ) from e
    return component
def sanitize_html(str):
    """
    Escape all the HTML/XML special characters with their unicode escapes, so
    value is safe to be output in JSON.
    This is the same internals as `django.utils.html.json_script` except it takes a string
    instead of an object to avoid calling DjangoJSONEncoder.
    """
    str = str.translate(_json_script_escapes)
    return mark_safe(str)
@timed
def set_property_from_data(
    component_or_field: Union[UnicornView, UnicornField, Model], name: str, value: Any,
) -> None:
    """
    Sets properties on the component based on passed-in data.
    """
    try:
        if not hasattr(component_or_field, name):
            return
    except ValueError:
        return
    field = getattr(component_or_field, name)
    component_field_is_model_or_unicorn_field = _is_component_field_model_or_unicorn_field(
        component_or_field, name
    )
    if component_field_is_model_or_unicorn_field:
        field = getattr(component_or_field, name)
        type_hints = get_type_hints(component_or_field)
        if isinstance(value, dict):
            for key in value.keys():
                key_value = value[key]
                set_property_from_data(field, key, key_value)
    elif hasattr(field, "related_val"):
        field.set(value)
    else:
        type_hints = get_type_hints(component_or_field)
        type_hint = type_hints.get(name)
        if _is_queryset(field, type_hint, value):
            value = _create_queryset(field, type_hint, value)
        elif type_hint:
            if is_dataclass(type_hint):
                value = type_hint(**value)
            else:
                try:
                    value = type_hint(value)
                except TypeError:
                    pass
        if hasattr(component_or_field, "_set_property"):
            component_or_field._set_property(name, value)
        else:
            setattr(component_or_field, name, value)
@timed
def _is_component_field_model_or_unicorn_field(
    component_or_field: Union[UnicornView, UnicornField, Model], name: str,
) -> bool:
    """
    Determines whether a component's field is a Django `Model` or `UnicornField` either
    by checking the field's instance or inspecting the type hints.
    One side-effect is that the field will be instantiated if it is currently `None` and
    the type hint is available.
    Args:
        component: `UnicornView` to check.
        name: Name of the field.
    Returns:
        Whether the field is a Django `Model` or `UnicornField`.
    """
    field = getattr(component_or_field, name)
    if isinstance(field, UnicornField) or isinstance(field, Model):
        return True
    is_subclass_of_model = False
    is_subclass_of_unicorn_field = False
    component_type_hints = {}
    try:
        component_type_hints = get_type_hints(component_or_field)
        if name in component_type_hints:
            is_subclass_of_model = issubclass(component_type_hints[name], Model)
            if not is_subclass_of_model:
                is_subclass_of_unicorn_field = issubclass(
                    component_type_hints[name], UnicornField
                )
            if field is None:
                if is_subclass_of_model or is_subclass_of_unicorn_field:
                    field = component_type_hints[name]()
                    setattr(component_or_field, name, field)
