                prefix = prefix + u'('
                fragment = fragment[1:]
                if fragment.endswith(u')'):
                    suffix = u')' + suffix
                    fragment = fragment[:-1]
                continue
            if fragment.endswith(u')') and u'(' not in fragment:
                fragment = fragment[:-1]
                suffix = u')' + suffix
                continue
            if fragment.endswith(u','):
                fragment = fragment[:-1]
                suffix = u',' + suffix
                continue
            if fragment.endswith(u'.'):
                fragment = fragment[:-1]
                suffix = u'.' + suffix
                continue
            break
        return fragment, prefix, suffix
