class RdiffRepo(object):
    def __init__(self, user_root, path, encoding):
        if isinstance(user_root, str):
            user_root = os.fsencode(user_root)
        if isinstance(path, str):
            path = os.fsencode(path)
        assert isinstance(user_root, bytes)
        assert isinstance(path, bytes)
        assert encoding
        self._encoding = encodings.search_function(encoding)
        assert self._encoding
        self.path = path.strip(b"/")
        if self.path:
            self.full_path = os.path.normpath(os.path.join(user_root, self.path))
        else:
            self.full_path = os.path.normpath(user_root)
        self._data_path = os.path.join(self.full_path, RDIFF_BACKUP_DATA)
        assert isinstance(self._data_path, bytes)
        self._increment_path = os.path.join(self._data_path, INCREMENTS)
        self.current_mirror = MetadataDict(self, CurrentMirrorEntry)
        self.error_log = MetadataDict(self, LogEntry)
        self.mirror_metadata = MetadataDict(self, MirrorMetadataEntry)
        self.file_statistics = MetadataDict(self, FileStatisticsEntry)
        self.session_statistics = MetadataDict(self, SessionStatisticsEntry)
    def _decode(self, value, errors='replace'):
        """Used to decode a repository path into unicode."""
        assert isinstance(value, bytes)
        return self._encoding.decode(value, errors)[0]
    def listdir(self, path):
        """
        Return a list of RdiffDirEntry each representing a file or a folder in the given path.
        """
        full_path = os.path.realpath(os.path.join(self.full_path, path.strip(b'/')))
        relative_path = os.path.relpath(full_path, self.full_path)
        if relative_path.startswith(RDIFF_BACKUP_DATA):
            raise DoesNotExistError(path)
        increment_path = os.path.normpath(os.path.join(self._increment_path, relative_path))
        if not full_path.startswith(self.full_path) or not increment_path.startswith(self.full_path):
            raise AccessDeniedError('%s make reference outside the repository' % self._decode(path))
        try:
            existing_items = os.listdir(full_path)
            if relative_path == b'.':
                existing_items.remove(RDIFF_BACKUP_DATA)
        except (NotADirectoryError, FileNotFoundError):
            existing_items = None
        except OSError:
            raise AccessDeniedError(path)
        try:
            increment_items = os.listdir(increment_path)
        except (NotADirectoryError, FileNotFoundError):
            increment_items = None
        except OSError:
            raise AccessDeniedError(path)
        if existing_items is None and increment_items is None:
            raise DoesNotExistError(path)
        entries = {}
        for name in existing_items or []:
            entries[name] = RdiffDirEntry(
                self,
                os.path.normpath(os.path.join(relative_path, name)),
                exists=True,
                increments=[],
            )
        for item in increment_items or []:
            try:
                increment = IncrementEntry(item)
            except ValueError:
                continue
            entry = entries.get(increment.name, None)
            if not entry:
                entry = entries[increment.name] = RdiffDirEntry(
                    self,
                    os.path.normpath(os.path.join(relative_path, increment.name)),
                    exists=False,
                    increments=[increment] if increment else [],
                )
            else:
                bisect.insort_left(entry._increments, increment)
        return sorted(list(entries.values()), key=lambda e: e.path)
    def fstat(self, path):
        """Return a new instance of DirEntry to represent the given path."""
        assert isinstance(path, bytes)
        full_path = os.path.normpath(os.path.join(self.full_path, path.strip(b'/')))
        increment_path = os.path.normpath(os.path.join(self._increment_path, path.strip(b'/'), b'..'))
        if not full_path.startswith(self.full_path) or not increment_path.startswith(self.full_path):
            raise AccessDeniedError('%s make reference outside the repository' % self._decode(path))
        relative_path = os.path.relpath(full_path, self.full_path)
        if relative_path.startswith(RDIFF_BACKUP_DATA):
            raise DoesNotExistError(path)
        if relative_path == b'.':
            return RdiffDirEntry(self, b'', True, [])
        try:
            os.lstat(full_path)
            exists = True
        except (OSError, ValueError):
            exists = False
        increment_items = os.listdir(increment_path)
        prefix = os.path.basename(full_path)
        entry = RdiffDirEntry(self, relative_path, exists, [])
        for item in increment_items:
            if not item.startswith(prefix):
                continue
            try:
                increment = IncrementEntry(item)
            except ValueError:
                continue
            if increment.name != prefix:
                continue
            bisect.insort_left(entry._increments, increment)
        if not exists and not entry._increments:
            logger.error("path [%r] doesn't exists", path)
            raise DoesNotExistError(path)
        return entry
    def get_display_name(self, path):
        """
        Return proper display name of the given path according to repository encoding and quoted characters.
        """
        assert isinstance(path, bytes)
        path = path.strip(b'/')
        if path in [b'.', b'']:
            if not self.path:
                return self._decode(unquote(os.path.basename(self.full_path)))
            return self._decode(unquote(self.path))
        else:
            return self._decode(unquote(os.path.basename(path)))
def validate_int(value, message=None):
    """Raise HTTP Error if the value is not an integer"""
    try:
        return int(value)
    except ValueError:
        raise cherrypy.HTTPError(400, message)
def flash(message, level='info'):
    """
    Add a flashin message to the session.
    """
    assert message
    assert level in ['info', 'error', 'warning', 'success']
    if 'flash' not in cherrypy.session:
        cherrypy.session['flash'] = []
    flash_message = FlashMessage(message, level)
    cherrypy.session['flash'].append(flash_message)
@poppath()
class StatusPage(Controller):
    def _data(self, days):
        """
        Return number of backups per days including failure.
        """
        def _key(d):
            return time.strftime(str(d).split('T')[0])
        base = RdiffTime().set_time(0, 0, 0) - datetime.timedelta(days=days)
        data = {_key(base + datetime.timedelta(days=i)): [] for i in range(0, days + 1)}
        success = {_key(base + datetime.timedelta(days=i)): 0 for i in range(0, days + 1)}
        failure = success.copy()
        for repo in self.app.currentuser.repo_objs:
            if len(repo.session_statistics):
                for stat in repo.session_statistics[base:]:
                    key = _key(stat.date)
                    if key not in success:
                        continue
                    success[key] = success.get(key, 0) + 1
                    data[key].append(stat)
                    if stat.errors:
                        failure[key] += 1
        return {
            'backup_count': [
                {'name': _('Successful Backup'), 'data': success},
                {'name': _('Backup with errors'), 'data': failure},
            ],
            'data': data,
        }
def ugettext(message):
    """Standard translation function. You can use it in all your exposed
    methods and everywhere where the response object is available.
    :parameters:
        message : Unicode
            The message to translate.
    :returns: The translated message.
    :rtype: Unicode
    """
    if not hasattr(cherrypy.response, "i18n"):
        return message
    return cherrypy.response.i18n.trans.ugettext(message)
class LoginPage(Controller):
    @cherrypy.expose()
    @cherrypy.config(**{'tools.auth_form.on': False, 'tools.ratelimit.on': True})
    def index(self, **kwargs):
        form = LoginForm()
        if form.validate_on_submit():
            try:
                userobj = self.app.store.login(form.login.data, form.password.data)
            except Exception:
                logger.exception('fail to validate credential')
                flash(_("Fail to validate user credential."))
            else:
                if userobj:
                    cherrypy.session[SESSION_KEY] = userobj.username
                    raise cherrypy.HTTPRedirect(form.redirect.data)
                flash(_("Invalid username or password."))
        params = {'form': form}
        if self._welcome_msg:
            params["welcome_msg"] = self._welcome_msg.get('')
            if hasattr(cherrypy.response, 'i18n'):
                locale = cherrypy.response.i18n.locale.language
                params["welcome_msg"] = self._welcome_msg.get(locale, params["welcome_msg"])
        return self._compile_template("login.html", **params).encode("utf-8")

@poppath()
class DeletePage(Controller):
    @cherrypy.expose
    @cherrypy.tools.errors(
        error_table={
            DoesNotExistError: 404,
            AccessDeniedError: 403,
        }
    )
    def default(self, path=b"", **kwargs):
        repo, path = self.app.store.get_repo_path(path)
        path_obj = repo.fstat(path)
        is_maintainer()
        form = DeleteRepoForm()
        form.expected_confirm = path_obj.display_name
        if form.is_submitted():
            if form.validate():
                cherrypy.engine.publish('schedule_task', repo.delete, path)
                if path_obj.isroot:
                    raise cherrypy.HTTPRedirect(url_for('/'))
                else:
                    parent_path = repo.fstat(os.path.dirname(path_obj.path))
                    raise cherrypy.HTTPRedirect(url_for('browse', repo, parent_path))
            else:
                raise cherrypy.HTTPError(400, form.error_message)
        else:
            raise cherrypy.HTTPError(405)
def get_pyinfo():
    try:
        import distro
        yield _('OS Version'), '%s %s (%s %s)' % (
            platform.system(),
            platform.release(),
            distro.name().capitalize(),
            distro.version(),
        )
    except Exception:
        yield _('OS Version'), '%s %s' % (platform.system(), platform.release())
    if hasattr(os, 'path'):
        yield _('OS Path'), os.environ['PATH']
    if hasattr(sys, 'version'):
        yield _('Python Version'), ''.join(sys.version)
    if hasattr(sys, 'subversion'):
        yield _('Python Subversion'), ', '.join(sys.subversion)
    if hasattr(sys, 'prefix'):
        yield _('Python Prefix'), sys.prefix
    if hasattr(sys, 'executable'):
        yield _('Python Executable'), sys.executable
    if hasattr(sys, 'path'):
        yield _('Python Path'), ', '.join(sys.path)
def get_osinfo():
    def gr_name(gid):
        try:
            return grp.getgrgid(gid).gr_name
        except Exception:
            return
    def pw_name(uid):
        try:
            return pwd.getpwuid(os.getuid()).pw_name
        except Exception:
            return
    if hasattr(sys, 'getfilesystemencoding'):
        yield _('File System Encoding'), sys.getfilesystemencoding()
    if hasattr(os, 'getcwd'):
        yield _('Current Working Directory'), os.getcwd()
    if hasattr(os, 'getegid'):
        yield _('Effective Group'), '%s (%s)' % (os.getegid(), gr_name(os.getegid()))
    if hasattr(os, 'geteuid'):
        yield _('Effective User'), '%s (%s)' % (os.geteuid(), pw_name(os.geteuid))
    if hasattr(os, 'getgid'):
        yield _('Group'), '%s (%s)' % (os.getgid(), gr_name(os.getgid()))
    if hasattr(os, 'getuid'):
        yield _('User'), '%s (%s)' % (os.getuid(), gr_name(os.getuid()))
    if hasattr(os, 'getgroups'):
        yield _('Group Membership'), ', '.join(['%s (%s)' % (gid, gr_name(gid)) for gid in os.getgroups()])
    try:
        if hasattr(os, 'getpid') and hasattr(os, 'getppid'):
            yield _('Process ID'), ('%s (parent: %s)' % (os.getpid(), os.getppid()))
    except Exception:
        pass
